  function resolveCode(text){const q=String(text).trim();if(/^[0-9]{4,6}[A-Za-z]?$/.test(q))return q.toUpperCase();const matches=Object.entries(window._names||{}).filter(([c,n])=>/^[0-9]{4,6}[A-Za-z]?$/.test(c)&&n===q);if(matches.length===1)return matches[0][0];throw Error('請從搜尋建議選擇標的，或輸入股票／ETF 代號');}
