      legend.querySelectorAll('[data-ma-period]').forEach(b=>b.onclick=()=>{const n=+b.dataset.maPeriod;maVisibility.set(n,!maVisibility.get(n));draw(rows,strategy,trades,range);});
      readout.textContent=rows.length?`${rows[0].time} ～ ${rows.at(-1).time} · 收盤 ${rows.at(-1).close.toLocaleString()} · ${trades.length?'買賣點為已執行回測結果':'指標預覽，尚無回測買賣點'}`:'尚無行情';
      if(!window.LightweightCharts){fallback(rows,overlays);sub.hidden=true;return;}
      if(!chart){chart=LightweightCharts.createChart(panel,options(330));candles=chart.addCandlestickSeries({upColor:'#df665d',downColor:'#349a75',borderVisible:false,wickUpColor:'#df665d',wickDownColor:'#349a75',priceLineVisible:false});chart.subscribeCrosshairMove(p=>{const x=p.seriesData?.get(candles);if(x)readout.textContent=`${p.time} · 開 ${x.open.toFixed(2)} 高 ${x.high.toFixed(2)} 低 ${x.low.toFixed(2)} 收 ${x.close.toFixed(2)}`;});chart.subscribeClick(p=>{if(typeof p.time==='string')onDate?.(p.time);});observer=new ResizeObserver(()=>{if(chart)chart.applyOptions({width:Math.max(260,panel.clientWidth)});if(lowerChart)lowerChart.applyOptions({width:Math.max(260,panel.clientWidth)});});observer.observe(panel);}
      const light=options(330);chart.applyOptions({layout:light.layout,grid:light.grid});candles.setData(rows.map(x=>({time:x.time,open:x.open,high:x.high,low:x.low,close:x.close})));
