      candles.setMarkers(trades.map(t=>({time:t.date,position:t.side==='買進'?'belowBar':'aboveBar',color:t.side==='買進'?'#d96855':'#389878',shape:t.side==='買進'?'arrowUp':'arrowDown',text:trades.length>30?'':t.side==='買進'?'買':'賣'})));
