      indicatorChoice=Math.min(indicatorChoice,Math.max(0,oscillators.length-1));const select=host.querySelector('.ms-indicator-tools select');if(select){select.value=String(indicatorChoice);select.onchange=()=>{indicatorChoice=+select.value;draw(rows,strategy,trades,range);};}
