      if(oscillators.length){lowerChart=LightweightCharts.createChart(sub,options(145));const r=oscillators[indicatorChoice],values=E.indicators(rows,r);['left','right'].forEach((k,i)=>{const line=lowerChart.addLineSeries({crosshairMarkerRadius:1.5,crosshairMarkerBorderWidth:0,color:colors[i],lineWidth:1,priceLineVisible:false,lastValueVisible:true});line.setData(rows.map((x,j)=>({time:x.time,value:values[k][j]})).filter(x=>Number.isFinite(x.value)));});if(range)lowerChart.timeScale().setVisibleRange(range);else lowerChart.timeScale().setVisibleLogicalRange({from:Math.max(0,rows.length-150),to:rows.length+2});}
