    state.strategies=Array.isArray(state.strategies)?state.strategies:[];const editId=sessionStorage.getItem('academy.strategy.editId');sessionStorage.removeItem('academy.strategy.editId');const edited=state.strategies.find(x=>x.id===editId);if(edited){strategy=copy(edited);selectedId=edited.id;}
